exercises.solution:
int a = 15, b = 28;
System.out.println("Max: " + Math.max(a, b));
System.out.println("Min: " + Math.min(a, b));

double x = 5.7;
System.out.println(Math.ceil(x));
System.out.println(Math.floor(x));
System.out.println(Math.round(x));

System.out.println("PI: " + Math.PI);
System.out.println("E: " + Math.E);
double circumference = 2 * Math.PI * 5;
System.out.println("Obwod: " + circumference);

double d = Math.random();
int i = (int) (Math.random() * 10) + 1;
System.out.println(d);
System.out.println(i);

double angle = Math.toRadians(45);
System.out.println("sin: " + Math.sin(angle));
System.out.println("cos: " + Math.cos(angle));
System.out.println("tan: " + Math.tan(angle));

int a = 3, b = 4;
double c = Math.sqrt(a * a + b * b);
System.out.println(c);

System.out.println(Math.round(2.5)); // 3
System.out.println(Math.rint(2.5));  // 2.0
System.out.println(Math.round(3.5)); // 4
System.out.println(Math.rint(3.5));  // 4.0
// round() ZAWSZE zaokrągla .5 w gore.
// rint() stosuje 'round half to even' (bankierskie zaokrąglenie) -
// zaokrągla .5 do NAJBLIŻSZEJ PARZYSTEJ liczby, więc 2.5->2.0, ale 3.5->4.0.

int a = 12, b = 45, c = 27;
int max = Math.max(Math.max(a, b), c);
System.out.println(max);

double value = 150.0, min = 0.0, max = 100.0;
double clamped = Math.max(min, Math.min(max, value));
System.out.println("Przycieta wartość: " + clamped);

double radius = 7.5;
double area = Math.PI * radius * radius;
double rounded = Math.round(area * 100) / 100.0;
System.out.println(rounded);

int sum = 0;
for (int i = 0; i < 5; i++) {
    int r = (int) (Math.random() * 100) + 1;
    System.out.println(r);
    sum += r;
}
System.out.println("Suma: " + sum);
System.out.println("Średnia: " + (sum / 5.0));

for (int i = 0; i <= 10; i++) {
    System.out.println("2^" + i + " = " + (int) Math.pow(2, i));
}

for (int x = 0; x <= 3; x++) {
    System.out.println("exp(" + x + ") = " + Math.exp(x));
}

double radius = 4;
double volume = (4.0 / 3.0) * Math.PI * Math.pow(radius, 3);
System.out.println(volume);

double value = 3.14159265;
for (int n = 2; n <= 4; n++) {
    double factor = Math.pow(10, n);
    double rounded = Math.round(value * factor) / factor;
    System.out.println(n + " miejsc: " + rounded);
}

int[] degrees = {30, 45, 60, 90, 180};
for (int d : degrees) {
    double radians = Math.toRadians(d);
    double backToDegrees = Math.toDegrees(radians);
    System.out.println(d + " stopni = " + radians + " radianow = " + backToDegrees + " stopni");
}

int[] values = {1, 2, 4, 8, 16, 32};
for (int v : values) {
    double log2 = Math.log(v) / Math.log(2);
    System.out.println("log2(" + v + ") = " + log2);
}

double[] data = {4.5, 7.2, 1.8, 9.3, 5.6};
double min = data[0], max = data[0], sum = 0;
for (double d : data) {
    min = Math.min(min, d);
    max = Math.max(max, d);
    sum += d;
}
System.out.println("Min: " + min);
System.out.println("Max: " + max);
System.out.println("Suma: " + sum);
System.out.println("Średnia: " + (sum / data.length));

int x1 = 3, y1 = 4, x2 = 7, y2 = 1;
double distance = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
System.out.println(distance);

double P = 1000, r = 0.05;
int n = 12, t = 3;
double A = P * Math.pow(1 + r / n, n * t);
System.out.println(A);

int[] scores = {70, 80, 85, 90, 95};
double sum = 0;
for (int s : scores) {
    sum += s;
}
double mean = sum / scores.length;

double sumSquaredDiffs = 0;
for (int s : scores) {
    sumSquaredDiffs += Math.pow(s - mean, 2);
}
double stdDev = Math.sqrt(sumSquaredDiffs / scores.length);
System.out.println("Odchylenie standardowe: " + stdDev);

System.out.println(Math.toDegrees(Math.asin(0.5)));
System.out.println(Math.toDegrees(Math.acos(0.5)));
System.out.println(Math.toDegrees(Math.atan(1.0)));

for (int i = 0; i < 10; i++) {
    int die1 = (int) (Math.random() * 6) + 1;
    int die2 = (int) (Math.random() * 6) + 1;
    System.out.println("Rzut " + (i + 1) + ": " + die1 + " + " + die2 + " = " + (die1 + die2));
}

int N = 10000;
int inside = 0;
for (int i = 0; i < N; i++) {
    double x = Math.random();
    double y = Math.random();
    if (x * x + y * y <= 1) {
        inside++;
    }
}
double piApprox = 4.0 * inside / N;
System.out.println("Aproksymacja pi: " + piApprox);
System.out.println("Math.PI: " + Math.PI);

double n = 25;
double guess = n / 2;
double newGuess = (guess + n / guess) / 2;
while (Math.abs(guess - newGuess) > 0.0001) {
    guess = newGuess;
    newGuess = (guess + n / guess) / 2;
}
System.out.println("Metoda Newtona: " + newGuess);
System.out.println("Math.sqrt(25): " + Math.sqrt(25));

